import AppKit
import TOMLKit
import XCTest
import PaletteCore
import PalettePlatform
@testable import PaletteApp

/// Regression cover for the 2.20 theming audit: stale generated files, the
/// wallpaper card guard, managed-policy scopes and removal, bat/btop manual
/// setup, the wallpaper folder, unknown config values and the deck frame.
@MainActor
final class ThemingAuditTests: XCTestCase {
    private func makePaths() -> PalettePaths {
        let base = URL(fileURLWithPath: NSTemporaryDirectory())
            .appendingPathComponent("palette-audit-\(UUID().uuidString)", isDirectory: true)
        return PalettePaths(
            home: base.path,
            configDir: base.appendingPathComponent("config", isDirectory: true),
            stateDir: base.appendingPathComponent("state", isDirectory: true),
            cacheDir: base.appendingPathComponent("cache", isDirectory: true)
        )
    }

    private func makeEngine(
        _ paths: PalettePaths,
        installed: Set<String> = [],
        silent: Bool = false,
        legacy: Bool = false,
        reloadsEnabled: Bool = false
    ) -> ThemingEngine {
        let silentPath: @Sendable (String) -> String = { bundleID in
            paths.home + "/managed/\(bundleID).plist"
        }
        return ThemingEngine(
            paths: paths,
            themesDirectory: paths.themesDir,
            chromiumProbe: ThemingEngine.ChromiumProbe(
                installed: { installed },
                isRunning: { _ in false },
                silentActive: { _ in silent },
                legacyProfile: { _ in legacy },
                silentPath: silentPath
            ),
            reloadsEnabled: reloadsEnabled
        )
    }

    private func write(_ text: String, to url: URL) throws {
        try FileManager.default.createDirectory(
            at: url.deletingLastPathComponent(),
            withIntermediateDirectories: true
        )
        try text.write(to: url, atomically: true, encoding: .utf8)
    }

    // MARK: - Stale generated files

    func testStalenessFindsAMismatchedThemeIDAndOldHashHeaders() throws {
        let themeDir = URL(fileURLWithPath: NSTemporaryDirectory())
            .appendingPathComponent("palette-stale-\(UUID().uuidString)", isDirectory: true)
        try write(
            #"{"theme_id": "old-theme"}"#,
            to: themeDir.appendingPathComponent(ThemingRenderer.paletteJSONName)
        )
        try write("# generated by Palette\nlocal p = {}\n", to: themeDir.appendingPathComponent("nvim.lua"))
        try write("# generated by Palette\nthemes {}\n", to: themeDir.appendingPathComponent("zellij.kdl"))

        let reasons = ThemingStaleness.reasons(themeID: "default-dark", themeDir: themeDir)
        XCTAssertEqual(reasons.count, 3)
        XCTAssertTrue(reasons.contains { $0.contains("old-theme") })
        XCTAssertTrue(reasons.contains { $0.contains("nvim.lua") })
        XCTAssertTrue(reasons.contains { $0.contains("zellij.kdl") })
    }

    func testStalenessIsQuietForCorrectFiles() throws {
        let themeDir = URL(fileURLWithPath: NSTemporaryDirectory())
            .appendingPathComponent("palette-fresh-\(UUID().uuidString)", isDirectory: true)
        try write(
            #"{"theme_id": "default-dark"}"#,
            to: themeDir.appendingPathComponent(ThemingRenderer.paletteJSONName)
        )
        try write("-- generated by Palette\nlocal p = {}\n", to: themeDir.appendingPathComponent("nvim.lua"))
        try write("// generated by Palette\nthemes {}\n", to: themeDir.appendingPathComponent("zellij.kdl"))

        XCTAssertEqual(ThemingStaleness.reasons(themeID: "default-dark", themeDir: themeDir), [])
    }

    // MARK: - Wallpaper card guard

    func testWallpaperCardNeverEnablesTheming() {
        var config = ThemingConfig()
        config.enabled = false
        config.source = .wallpaper
        XCTAssertFalse(ThemingEngine.shouldApplyWallpaperCard(config))

        // Enabled alone is not enough: the Theme source keeps the picked theme
        // in charge and a card only changes the desktop picture.
        config.enabled = true
        config.source = .theme
        XCTAssertFalse(ThemingEngine.shouldApplyWallpaperCard(config))

        config.source = .wallpaper
        XCTAssertTrue(ThemingEngine.shouldApplyWallpaperCard(config))
    }

    func testMissingDesktopPictureNamesTheReportedPath() {
        let message = ThemingEngine.missingWallpaperMessage(
            path: "~/dot-files/wallpapers/aetheria-1.jpg"
        )
        XCTAssertEqual(
            message,
            "Desktop picture ~/dot-files/wallpapers/aetheria-1.jpg is missing — choose a new one."
        )
        XCTAssertEqual(
            ThemingEngine.missingWallpaperMessage(path: nil),
            "No desktop picture found — choose one."
        )
    }

    // MARK: - Chromium policy

    func testManagedPreferencePathsCoverDeviceAndUserScope() {
        let paths = ChromiumPolicy.managedPreferencePaths(
            bundleID: "com.google.Chrome",
            user: "myleshen"
        )
        XCTAssertEqual(paths, [
            "/Library/Managed Preferences/com.google.Chrome.plist",
            "/Library/Managed Preferences/myleshen/com.google.Chrome.plist",
            "/Library/Managed Preferences/myleshen/complete.plist",
        ])
    }

    func testUserScopeDetectionAndSeededColour() async throws {
        let palette = PalettePalette(theme: .defaultDark)
        let browser = try XCTUnwrap(ChromiumBrowser.browser(for: .chrome))
        let xml = ChromiumPolicy.mobileConfig(browser: browser, palette: palette)
        XCTAssertEqual(
            ChromiumPolicy.themeColor(in: Data(xml.utf8), bundleID: browser.bundleID),
            palette.background,
            "an exported profile's seeded colour must be readable"
        )

        // `complete.plist` is shared, so only the browser's own domain counts.
        let complete = try PropertyListSerialization.data(
            fromPropertyList: [
                browser.bundleID: ["BrowserThemeColor": palette.background],
            ],
            format: .xml,
            options: 0
        )
        XCTAssertTrue(ChromiumPolicy.carriesDomain(browser.bundleID, in: complete))
        XCTAssertFalse(ChromiumPolicy.carriesDomain("com.brave.Browser", in: complete))
        XCTAssertEqual(
            ChromiumPolicy.themeColor(in: complete, bundleID: browser.bundleID),
            palette.background
        )
    }

    func testSilentModeStatusReplacesTheReapprovalFlow() async throws {
        let paths = makePaths()
        let browser = try XCTUnwrap(ChromiumBrowser.browser(for: .helium))
        let engine = makeEngine(paths, installed: [browser.bundleID], silent: true)
        let applied = await engine.apply(
            ThemingConfig(enabled: true, theme: "default-dark", targets: ["helium"])
        )

        let target = try XCTUnwrap(applied.targets.first { $0.id == "helium" })
        XCTAssertEqual(target.note, "Managed — updates silently.")
        XCTAssertFalse(applied.status.contains("System Settings"))
        XCTAssertFalse(applied.status.contains("Re-approve"))
    }

    func testOldProfileIsDetectedForTheOneTimeMigration() {
        let identifiers = ChromiumPolicy.allPolicyIdentifiers()
        XCTAssertEqual(identifiers.count, 6, "every BrowserThemeColor browser, not Arc")
        XCTAssertTrue(identifiers.contains(ChromiumPolicy.identifier(for: "com.google.Chrome")))
        XCTAssertTrue(identifiers.contains(ChromiumPolicy.identifier(for: "com.brave.Browser")))
        XCTAssertFalse(identifiers.contains(ChromiumPolicy.identifier(for: "company.thebrowser.Browser")))
    }

    // MARK: - bat and btop

    func testBatCacheCommandIsTheDocumentedOne() {
        XCTAssertEqual(ThemingIncludes.batCacheArguments, ["bat", "cache", "--build"])
    }

    func testBtopIsManualAndStripsALegacyBlock() throws {
        let paths = makePaths()
        let includes = ThemingIncludes(
            home: paths.home,
            themeDir: paths.themeDir
        )
        try FileManager.default.createDirectory(at: paths.themeDir, withIntermediateDirectories: true)
        try write("theme body\n", to: paths.themeDir.appendingPathComponent("btop.theme"))
        let config = URL(fileURLWithPath: paths.home + "/.config/btop/btop.conf")
        try write(
            "color_theme = \"Default\"\n# >>> palette theme >>>\ncolor_theme = \"palette\"\n# <<< palette theme <<<\n",
            to: config
        )

        let palette = PalettePalette(theme: .defaultDark)
        let metadata = PaletteMetadata(source: "theme", theme: "Default Dark", appearance: "dark")
        let outcome = includes.install(.btop, palette: palette, metadata: metadata)
        XCTAssertNil(outcome.error)

        let updated = try String(contentsOf: config, encoding: .utf8)
        XCTAssertEqual(updated, "color_theme = \"Default\"\n", "the old block must be gone")
        XCTAssertFalse(updated.contains("color_theme = \"palette\""))
        XCTAssertTrue(FileManager.default.fileExists(
            atPath: paths.home + "/.config/btop/themes/palette.theme"
        ))
        XCTAssertTrue(includes.status(for: .btop).note.contains("Manual"))
    }

    // MARK: - Wallpaper folder

    func testEmptyWallpaperFolderMeansEmpty() {
        XCTAssertNil(WallpaperLibrary.directory(path: ""))
        XCTAssertNil(WallpaperLibrary.directory(path: "   "))
        XCTAssertEqual(WallpaperLibrary.files(in: nil), [])
        XCTAssertEqual(
            WallpaperLibrary.files(in: URL(fileURLWithPath: "/definitely/not/a/folder")),
            []
        )
        var config = ThemingConfig()
        config.wallpaperDirectory = ""
        XCTAssertEqual(config.normalized().wallpaperDirectory, "")
    }

    // MARK: - Inline KDL headers

    func testStripHeaderRemovesEveryCommentMarker() {
        let includes = ThemingIncludes(
            home: NSTemporaryDirectory(),
            themeDir: URL(fileURLWithPath: NSTemporaryDirectory())
        )
        XCTAssertEqual(
            includes.stripHeader("# generated by Palette\n# source: theme\n\nthemes {}\n"),
            "themes {}"
        )
        XCTAssertEqual(
            includes.stripHeader("// generated by Palette\n// source: theme\n\nthemes {}\n"),
            "themes {}"
        )
        XCTAssertEqual(
            includes.stripHeader("-- generated by Palette\n-- source: theme\n\nlocal p = {}\n"),
            "local p = {}"
        )
    }

    // MARK: - Reset

    func testResetRemovesEveryInclude() async throws {
        let paths = makePaths()
        let kitty = URL(fileURLWithPath: paths.home + "/.config/kitty/kitty.conf")
        try write("user kitty\n", to: kitty)
        let engine = makeEngine(paths)
        _ = await engine.apply(ThemingConfig(enabled: true, theme: "default-dark", targets: ["kitty"]))
        XCTAssertTrue(try String(contentsOf: kitty, encoding: .utf8).contains("palette theme"))

        let outcomes = engine.removeAllIncludes()
        XCTAssertFalse(outcomes.isEmpty)
        XCTAssertEqual(try String(contentsOf: kitty, encoding: .utf8), "user kitty\n")
    }

    // MARK: - Config diagnostics

    func testUnknownTargetsAndDarkModeProduceWarnings() throws {
        let table = try TOMLTable(string: """
        [theming]
        enabled = true
        dark_mode = "sepia"
        targets = ["kitty", "not-a-target"]
        """)
        let parsed = ThemingConfig.parse(try XCTUnwrap(table.table("theming")))
        XCTAssertEqual(parsed.targets, ["kitty"])
        XCTAssertEqual(parsed.darkMode, "auto")

        let diagnostics = ThemingConfig.diagnostics(for: try XCTUnwrap(table.table("theming")))
        XCTAssertEqual(diagnostics.count, 2)
        XCTAssertTrue(diagnostics.allSatisfy { $0.level == .warning })
        XCTAssertTrue(diagnostics.contains { $0.message.contains("not-a-target") })
        XCTAssertTrue(diagnostics.contains { $0.message.contains("sepia") })
    }

    // MARK: - Deck

    func testDeckFrameClampsToTheVisibleScreen() {
        let normal = NSRect(x: 0, y: 0, width: 1440, height: 900)
        let centered = ThemeGalleryLayout.frame(in: normal)
        XCTAssertEqual(centered.width, ThemeGalleryLayout.panelWidth)
        XCTAssertEqual(centered.height, ThemeGalleryLayout.panelHeight)
        XCTAssertTrue(normal.contains(centered))

        let small = NSRect(x: 0, y: 0, width: 1000, height: 600)
        let clamped = ThemeGalleryLayout.frame(in: small)
        XCTAssertLessThanOrEqual(clamped.width, small.width - 2 * ThemeGalleryLayout.margin)
        XCTAssertLessThanOrEqual(clamped.height, small.height - 2 * ThemeGalleryLayout.margin)
        XCTAssertTrue(small.contains(clamped))
        XCTAssertGreaterThanOrEqual(clamped.minX, small.minX + ThemeGalleryLayout.margin)
        XCTAssertGreaterThanOrEqual(clamped.minY, small.minY + ThemeGalleryLayout.margin)
    }

    func testShowingTheDeckClearsTheFilter() {
        let model = ThemeGalleryModel()
        model.deck.query = "gruvbox"
        model.deck.favouritesOnly = true
        model.showAll()
        XCTAssertEqual(model.deck.query, "")
        XCTAssertFalse(model.deck.favouritesOnly)
    }

    // MARK: - Rendering

    func testFollowWallpaperRendersFalseUnlessTheSourceIsWallpaper() {
        var config = ThemingConfig()
        config.followWallpaper = true
        XCTAssertTrue(config.render().contains("follow_wallpaper = false"))

        config.source = .wallpaper
        XCTAssertTrue(config.render().contains("follow_wallpaper = true"))
    }
}
